    10	export interface OrderAggregate {
    11	  order: Order;
    12	  payment?: Payment;
    13	  shipment?: Shipment;
    14	}
    15	
    16	export interface OrderQuery {
    17	  status?: string;
    18	  customer?: string;
    19	}
    20	
    21	export class OrderQueryService {
    22	  constructor(
    23	    private readonly orders: OrderRepository,
    24	    private readonly payments: PaymentRepository,
    25	    private readonly shipments: ShipmentRepository,
    26	  ) {}
    27	
    28	  find(q: OrderQuery = {}): OrderAggregate[] {
    29	    if (q.status !== undefined && !isOrderStatus(q.status)) {
    30	      throw new Error(`unknown order status: ${q.status}`);
    31	    }
    32	    const rows = this.orders
    33	      .all()
    34	      .filter((o) => (q.status ? o.status === q.status : true))
    35	      .filter((o) => (q.customer ? o.customer === q.customer : true))
    36	      .map((order) => this.aggregate(order));
    37	    return sortBy(rows, (r) => orderPriority(r.order.status), (r) => -r.order.createdAt);
    38	  }
    39	
    40	  byId(id: string): OrderAggregate | undefined {
    41	    const order = this.orders.get(id);
    42	    return order ? this.aggregate(order) : undefined;
    43	  }
    44	
    45	  countByStatus(): Record<OrderStatus, number> {
    46	    const counts = Object.fromEntries(Object.values(OrderStatus).map((s) => [s, 0])) as Record<OrderStatus, number>;
    47	    for (const o of this.orders.all()) counts[o.status]++;
    48	    return counts;
    49	  }
    50	
    51	  private aggregate(order: Order): OrderAggregate {
    52	    return {
    53	      order,
    54	      payment: this.payments.latestFor(order.id),
    55	      shipment: this.shipments.get(order.id),
    56	    };
    57	  }
