    10	export function eq(actual: unknown, expected: unknown, label: string): void {
    11	  const a = JSON.stringify(actual);
    12	  const e = JSON.stringify(expected);
    13	  if (a !== e) throw new Error(`${label}: expected ${e}, got ${a}`);
    14	}
