import { ORDER_BADGES } from "./orderBadges";
import { PAYMENT_BADGES } from "./paymentBadges";
import { SHIPMENT_BADGES } from "./shipmentBadges";
import { Badge } from "./types";

export { Badge, Tone } from "./types";

// Each domain keeps its own table: raw status values collide across domains
// (e.g. order "PENDING" vs payment "PENDING", payment "FAILED" vs shipment "FAILED"),
// so they must never be merged into one flat map.
const BADGES_BY_KIND = {
  order: ORDER_BADGES,
  payment: PAYMENT_BADGES,
  shipment: SHIPMENT_BADGES,
} as const;

export type BadgeKind = keyof typeof BADGES_BY_KIND;

const UNKNOWN_TONE = "neutral" as const;

export function badgeFor(kind: BadgeKind, status: string): Badge {
  const table: Readonly<Record<string, Badge>> = BADGES_BY_KIND[kind];
  const badge = table[status];
  return badge ? { ...badge } : { label: status, tone: UNKNOWN_TONE };
}

export function knownStatuses(kind: BadgeKind): string[] {
  return Object.keys(BADGES_BY_KIND[kind]).sort();
}

